import { useCallback, useEffect, useState } from "react";
import {
  CheckCircle2,
  CircleDashed,
  FileText,
  Loader2,
  Pencil,
  Play,
  Plus,
  Radar,
  Trash2,
  X,
  XCircle,
} from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  DeleteDeployment,
  DeployPlanPreview,
  DeployPresets,
  GetDeployment,
  GetRunLog,
  ListDeployments,
  RunDetect,
  SaveDeployment,
  StartApply,
} from "../../wailsjs/go/controllers/Deployments";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListHosts } from "../../wailsjs/go/controllers/SSH";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type RunSummary = {
  id: string;
  kind: string;
  status: string;
  startedAt: string;
  endedAt: string;
  error?: string;
};

type DeploymentRecord = {
  id: string;
  name: string;
  updatedAt: string;
  runs?: RunSummary[];
};

type ApplyConfig = {
  projectName: string;
  kind: string;
  domain: string;
  environment: string;
  gitUrl: string;
  gitBranch: string;
  webServer: string;
  phpVersion: string;
  database: { engine: string; name: string };
  ssl: { enabled: boolean; email: string };
};

type View = {
  id: string;
  name: string;
  hostName: string;
  presetId: string;
  config: ApplyConfig;
  runs?: RunSummary[];
};

type Step = { title: string; command: string; sudo: boolean; ignore: boolean };

const EMPTY_CONFIG: ApplyConfig = {
  projectName: "",
  kind: "laravel",
  domain: "",
  environment: "production",
  gitUrl: "",
  gitBranch: "main",
  webServer: "nginx",
  phpVersion: "8.3",
  database: { engine: "mysql", name: "" },
  ssl: { enabled: false, email: "" },
};

// The deployments page: cards per deployment, an editor with a plan preview,
// and a live timeline fed by deploy:step / deploy:line events.
export default function Deployments() {
  const t = useT();
  const dialogs = useDialogs();
  const [records, setRecords] = useState<DeploymentRecord[]>([]);
  const [editing, setEditing] = useState<View | null>(null);
  const [hosts, setHosts] = useState<string[]>([]);
  const [presets, setPresets] = useState<{ id: string; name: string }[]>([]);
  // activeRun tracks the timeline shown while a run streams.
  const [activeRun, setActiveRun] = useState<{
    deploymentId: string;
    runId: string;
    steps: Record<number, { title: string; status: string }>;
    lines: string[];
  } | null>(null);
  const [logRunId, setLogRunId] = useState("");
  const [logText, setLogText] = useState("");

  const refresh = useCallback(() => {
    ListDeployments()
      .then((list: DeploymentRecord[]) => setRecords(list ?? []))
      .catch(() => {
        /* pre-startup */
      });
    ListHosts()
      .then((list: { name: string }[]) => setHosts((list ?? []).map((h) => h.name)))
      .catch(() => {});
    DeployPresets()
      .then((list: { id: string; name: string }[]) => setPresets(list ?? []))
      .catch(() => {});
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Stream one apply into the timeline panel.
  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    const cancelStep = EventsOn(
      "deploy:step",
      (p: { deploymentId: string; runId: string; index: number; title: string; status: string }) => {
        setActiveRun((prev) => {
          if (!prev || prev.runId !== p.runId) return prev;
          return {
            ...prev,
            steps: { ...prev.steps, [p.index]: { title: p.title, status: p.status } },
          };
        });
      }
    );
    // @ts-ignore EventsOn returns a cancel function
    const cancelLine = EventsOn(
      "deploy:line",
      (p: { deploymentId: string; runId: string; line: string }) => {
        setActiveRun((prev) => {
          if (!prev || prev.runId !== p.runId) return prev;
          return { ...prev, lines: [...prev.lines.slice(-400), p.line] };
        });
      }
    );
    // @ts-ignore EventsOn returns a cancel function
    const cancelDone = EventsOn(
      "deploy:done",
      (p: { deploymentId: string; runId: string; status: string; error: string }) => {
        setActiveRun((prev) => {
          if (!prev || prev.runId !== p.runId) return prev;
          return {
            ...prev,
            lines: [...prev.lines, p.status === "success" ? "✔ done" : `✘ ${p.error}`],
          };
        });
        refresh();
      }
    );
    return () => {
      cancelStep?.();
      cancelLine?.();
      cancelDone?.();
    };
  }, [refresh]);

  const edit = async (id: string) => {
    try {
      setEditing(await GetDeployment(id));
    } catch (error) {
      await dialogs.alert({ title: id, message: String(error) });
    }
  };

  const create = () => {
    setEditing({
      id: "",
      name: "",
      hostName: hosts[0] ?? "",
      presetId: "",
      config: { ...EMPTY_CONFIG },
    });
  };

  const save = async (view: View) => {
    try {
      await SaveDeployment(view as any);
      setEditing(null);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: view.name, message: String(error) });
    }
  };

  const remove = async (rec: DeploymentRecord) => {
    const yes = await dialogs.confirm({
      title: t("deployments.deleteConfirm", { name: rec.name }),
      danger: true,
    });
    if (!yes) return;
    await DeleteDeployment(rec.id);
    refresh();
  };

  const detect = async (rec: DeploymentRecord) => {
    try {
      await RunDetect(rec.id);
      refresh();
      const view = await GetDeployment(rec.id);
      const latest = view.runs?.[0];
      if (latest) {
        setLogRunId(latest.id);
        setLogText(await GetRunLog(latest.id));
      }
    } catch (error) {
      await dialogs.alert({ title: rec.name, message: String(error) });
    }
  };

  const apply = async (rec: DeploymentRecord) => {
    try {
      const runId = await StartApply(rec.id);
      setActiveRun({ deploymentId: rec.id, runId, steps: {}, lines: [] });
    } catch (error) {
      await dialogs.alert({ title: rec.name, message: String(error) });
    }
  };

  const openLog = async (run: RunSummary) => {
    setLogRunId(run.id);
    setLogText(await GetRunLog(run.id));
  };

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex items-center justify-between">
        <h1 className="text-lg font-semibold text-white/95">{t("deployments.title")}</h1>
        <button
          type="button"
          onClick={create}
          disabled={hosts.length === 0}
          title={hosts.length === 0 ? t("deployments.needHost") : undefined}
          className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85 disabled:opacity-40"
        >
          <Plus className="h-3.5 w-3.5" /> {t("deployments.new")}
        </button>
      </header>

      <div className="mt-3 min-h-0 flex-1 space-y-3 overflow-y-auto pr-0.5">
        {editing && (
          <DeploymentForm
            view={editing}
            hosts={hosts}
            presets={presets}
            onSave={save}
            onCancel={() => setEditing(null)}
          />
        )}

        {records.length === 0 && !editing && (
          <section className="glass p-8 text-center">
            <p className="text-sm text-white/50">{t("deployments.empty")}</p>
          </section>
        )}

        {records.map((rec) => (
          <article key={rec.id} className="glass p-3">
            <div className="flex items-center gap-3">
              <div className="min-w-0 flex-1">
                <span className="truncate text-sm font-medium text-white/90">{rec.name}</span>
                {rec.runs && rec.runs.length > 0 && (
                  <p className="mt-0.5 flex items-center gap-1.5 text-[11px] text-white/40">
                    <StatusIcon status={rec.runs[0].status} />
                    {t(`deployments.kind.${rec.runs[0].kind}`)} ·{" "}
                    {new Date(rec.runs[0].startedAt).toLocaleString()}
                  </p>
                )}
              </div>
              <div className="flex shrink-0 items-center gap-1">
                <button
                  type="button"
                  onClick={() => void detect(rec)}
                  title={t("deployments.detect")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Radar className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void apply(rec)}
                  title={t("deployments.apply")}
                  className="rounded border border-emerald-400/30 bg-emerald-500/10 p-1.5 text-emerald-300 hover:bg-emerald-500/20"
                >
                  <Play className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void edit(rec.id)}
                  title={t("deployments.edit")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Pencil className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void remove(rec)}
                  title={t("deployments.delete")}
                  className="rounded border border-red-400/30 bg-red-500/10 p-1.5 text-red-300 hover:bg-red-500/20"
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              </div>
            </div>

            {rec.runs && rec.runs.length > 0 && (
              <div className="mt-2 flex flex-wrap gap-1 border-t border-white/5 pt-2">
                {rec.runs.slice(0, 8).map((run) => (
                  <button
                    key={run.id}
                    type="button"
                    onClick={() => void openLog(run)}
                    title={new Date(run.startedAt).toLocaleString()}
                    className={`flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] ${
                      logRunId === run.id
                        ? "border-accent2/60 text-accent2"
                        : "border-white/10 text-white/40 hover:border-white/25 hover:text-white/70"
                    }`}
                  >
                    <StatusIcon status={run.status} />
                    {t(`deployments.kind.${run.kind}`)}
                  </button>
                ))}
              </div>
            )}
          </article>
        ))}

        {activeRun && (
          <section className="glass overflow-hidden">
            <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
              <span className="flex items-center gap-2 font-mono text-[11px] text-white/60">
                <Loader2 className="h-3 w-3 animate-spin text-accent2" />
                {t("deployments.running")}
              </span>
              <button
                type="button"
                onClick={() => setActiveRun(null)}
                className="rounded border border-white/10 p-1 text-white/60 hover:bg-white/10 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
            <div className="space-y-1 border-b border-white/5 px-3 py-2">
              {Object.entries(activeRun.steps).map(([index, step]) => (
                <div key={index} className="flex items-center gap-2 text-[11px]">
                  <StatusIcon status={step.status} />
                  <span
                    className={
                      step.status === "error"
                        ? "text-red-300"
                        : step.status === "ok"
                          ? "text-white/70"
                          : "text-white/90"
                    }
                  >
                    {step.title}
                  </span>
                </div>
              ))}
            </div>
            <pre className="max-h-48 overflow-auto bg-black/30 px-3 py-2 font-mono text-[10px] leading-relaxed text-white/60">
              {activeRun.lines.join("\n")}
            </pre>
          </section>
        )}

        {logRunId && logText && (
          <section className="glass overflow-hidden">
            <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
              <span className="flex items-center gap-2 font-mono text-[11px] text-white/60">
                <FileText className="h-3 w-3" /> {t("deployments.runLog")}
              </span>
              <button
                type="button"
                onClick={() => {
                  setLogRunId("");
                  setLogText("");
                }}
                className="rounded border border-white/10 p-1 text-white/60 hover:bg-white/10 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
            <pre className="max-h-64 overflow-auto bg-black/30 px-3 py-2 font-mono text-[10px] leading-relaxed text-white/60">
              {logText}
            </pre>
          </section>
        )}
      </div>
    </div>
  );
}

function StatusIcon({ status }: { status: string }) {
  switch (status) {
    case "success":
    case "ok":
      return <CheckCircle2 className="h-3 w-3 shrink-0 text-emerald-400" />;
    case "error":
      return <XCircle className="h-3 w-3 shrink-0 text-red-400" />;
    case "running":
      return <Loader2 className="h-3 w-3 shrink-0 animate-spin text-accent2" />;
    case "ignored":
      return <CircleDashed className="h-3 w-3 shrink-0 text-white/30" />;
    default:
      return <CircleDashed className="h-3 w-3 shrink-0 text-white/30" />;
  }
}

function DeploymentForm({
  view,
  hosts,
  presets,
  onSave,
  onCancel,
}: {
  view: View;
  hosts: string[];
  presets: { id: string; name: string }[];
  onSave: (view: View) => void;
  onCancel: () => void;
}) {
  const t = useT();
  const [draft, setDraft] = useState<View>(view);
  const [steps, setSteps] = useState<Step[]>([]);

  useEffect(() => {
    DeployPlanPreview(draft as any)
      .then((list: Step[]) => setSteps(list ?? []))
      .catch(() => setSteps([]));
  }, [draft]);

  const set = (patch: Partial<View>) => setDraft((d) => ({ ...d, ...patch }));
  const setConfig = (patch: Partial<ApplyConfig>) =>
    setDraft((d) => ({ ...d, config: { ...d.config, ...patch } }));

  const valid =
    draft.name.trim() !== "" &&
    draft.hostName !== "" &&
    draft.config.projectName.trim() !== "" &&
    draft.config.domain.trim() !== "";

  return (
    <section className="glass space-y-3 p-4">
      <div className="grid grid-cols-3 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.name")}</span>
          <input
            className="input w-full"
            value={draft.name}
            onChange={(e) => set({ name: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.host")}</span>
          <select
            className="input w-full"
            value={draft.hostName}
            onChange={(e) => set({ hostName: e.target.value })}
          >
            <option value="">—</option>
            {hosts.map((h) => (
              <option key={h} value={h}>
                {h}
              </option>
            ))}
          </select>
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.preset")}</span>
          <select
            className="input w-full"
            value={draft.presetId}
            onChange={(e) => set({ presetId: e.target.value })}
          >
            <option value="">{t("deployments.presetGenerated")}</option>
            {presets.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div className="grid grid-cols-4 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.project")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.projectName}
            onChange={(e) => setConfig({ projectName: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.domain")}</span>
          <input
            className="input w-full font-mono"
            placeholder="app.example.com"
            value={draft.config.domain}
            onChange={(e) => setConfig({ domain: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.environment")}</span>
          <select
            className="input w-full"
            value={draft.config.environment}
            onChange={(e) => setConfig({ environment: e.target.value })}
          >
            <option value="production">production</option>
            <option value="staging">staging</option>
            <option value="development">development</option>
          </select>
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.kindLabel")}</span>
          <select
            className="input w-full"
            value={draft.config.kind}
            onChange={(e) => setConfig({ kind: e.target.value })}
          >
            <option value="laravel">Laravel</option>
            <option value="static">Static</option>
          </select>
        </label>
      </div>

      <div className="grid grid-cols-4 gap-3">
        <label className="col-span-2 space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.gitUrl")}</span>
          <input
            className="input w-full font-mono"
            placeholder="https://github.com/user/repo.git"
            value={draft.config.gitUrl}
            onChange={(e) => setConfig({ gitUrl: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.branch")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.gitBranch}
            onChange={(e) => setConfig({ gitBranch: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.php")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.phpVersion}
            onChange={(e) => setConfig({ phpVersion: e.target.value })}
          />
        </label>
      </div>

      {steps.length > 0 && (
        <details className="rounded border border-white/10">
          <summary className="cursor-pointer px-3 py-1.5 text-[11px] text-white/50 hover:text-white/80">
            {t("deployments.planPreview", { count: steps.length })}
          </summary>
          <ol className="space-y-1 border-t border-white/10 px-3 py-2">
            {steps.map((step, i) => (
              <li key={i} className="font-mono text-[10px] text-white/50">
                {i + 1}. {step.title}
                {step.sudo ? " (sudo)" : ""}
              </li>
            ))}
          </ol>
        </details>
      )}

      <div className="flex justify-end gap-2 pt-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10"
        >
          {t("dialog.cancel")}
        </button>
        <button
          type="button"
          disabled={!valid}
          onClick={() => onSave(draft)}
          className="rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
        >
          {t("dialog.save")}
        </button>
      </div>
    </section>
  );
}
